function normalizeKind(raw) {
  if (raw === "short") return "short";
  if (raw === "film") return "film";
  if (raw === "novel") return "novel";
  return "drama";
}
function stageLabel(kind, stageId, fallback) {
  const k2 = normalizeKind(kind);
  return KINDS[k2].rename[stageId] || fallback;
}
function skipReason(kind, stageId) {
  const k2 = normalizeKind(kind);
  return KINDS[k2].skip[stageId] || "";
}

