K3(
  server,
  "continuity_gap",
  {
    description: "\u67E5\u8D26\u672C\u4E0E\u5267\u672C\u7684\u5DEE\u96C6\uFF1A\u54EA\u4E9B\u96C6\u5267\u672C\u5DF2\u7ECF\u5199\u4E86\u3001\u8D26\u672C\u8FD8\u6CA1\u8BB0\u3002\u5DEE\u96C6\u4E0D\u4E3A\u7A7A\u8BF4\u660E\u300C\u5199\u4E86\u6CA1\u8BB0\u300D\uFF0C\u4E0B\u4E00\u96C6\u4E00\u5B9A\u4F1A\u7A7F\u5E2E\u3002",
    inputSchema: { workingDir: external_exports.string() },
    _meta: { ui: { visibility: ["model", "app"] } }
  },
  async ({ workingDir }) => {
    workingDir = resolveProjectDir(workingDir).dir;
    const scriptDir = path12.join(workingDir, "09-\u5267\u672C");
    const kind = readProject(workingDir).kind || "drama";
    if (String(kind).toLowerCase() === "film") {
      const ACTS = ["\u7B2C\u4E00\u5E55", "\u7B2C\u4E8C\u5E55\u4E0A", "\u7B2C\u4E8C\u5E55\u4E0B", "\u7B2C\u4E09\u5E55"];
      let hasScript = false;
      if (existsSync11(scriptDir)) {
        for (const f2 of readdirSync8(scriptDir)) {
          if (!/\.fountain$/i.test(f2) || /\.bak$/i.test(f2)) continue;
          try {
            const body = readText3(path12.join(scriptDir, f2)).replace(/^\s*(Title|Episode|Logline|Notes|Author|Draft date):.*$/gim, "").replace(/\s/g, "");
            if (body.length >= 100) hasScript = true;
          } catch {
          }
        }
      }
      const rows2 = readContinuity(workingDir);
      const recorded = rows2.map((r2) => r2.ep);
      const missing = ACTS.filter((a) => !recorded.some((r2) => r2.replace(/\s/g, "").includes(a.replace(/\s/g, ""))));
      const complete2 = !hasScript || missing.length === 0;
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({
              ok: complete2,
              kind: "film",
              unit: "\u5E55\u6BB5",
              scriptWritten: hasScript,
              recordedCount: rows2.length,
              recorded,
              missing,
              hint: !hasScript ? "\u5168\u7247\u5267\u672C\u8FD8\u6CA1\u5199\uFF08\u53EA\u6709\u7A7A\u9AA8\u67B6\uFF09\uFF0C\u8D26\u672C\u81EA\u7136\u8FD8\u662F\u7A7A\u7684\u3002\u5199\u5B8C\u7B2C\u4E00\u5E55\u518D\u8BB0\u7B2C\u4E00\u884C\u3002" : !rows2.length ? `\u5168\u7247\u5267\u672C\u5DF2\u7ECF\u5199\u4E86\uFF0C\u4F46\u8D26\u672C\u4E00\u884C\u90FD\u6CA1\u6709\u3002\u73B0\u5728\u8865\u56DB\u884C\uFF08${ACTS.join(" / ")}\uFF09\uFF0C\u5426\u5219\u4E0B\u4E00\u5E55\u5C31\u4F1A\u7A7F\u5E2E\u3002` : missing.length ? `\u8D26\u672C\u8BB0\u4E86 ${rows2.length} \u884C\uFF0C\u4F46\u7F3A\uFF1A${missing.join("\u3001")}\u3002\u6BCF\u5199\u5B8C\u4E00\u5E55\u5C31\u8C03\u4E00\u6B21 append_continuity\uFF0Cep \u5199\u5E55\u6BB5\u540D\u3002` : "\u56DB\u5E55\u90FD\u5DF2\u5165\u8D26\u3002"
            })
          }
        ]
      };
    }
    const eps = [];
    if (existsSync11(scriptDir)) {
      for (const f2 of readdirSync8(scriptDir)) {
        if (/\.bak$/i.test(f2)) continue;
        const m2 = /\.fountain$/i.test(f2) ? f2.match(/^EP(\d+)/i) : f2.match(/第\s*0*(\d{1,3})\s*章/);
        if (m2) eps.push(String(Number(m2[1])).padStart(2, "0"));
      }
    }
    const gap = ledgerGap(workingDir, eps);
    const complete = eps.length > 0 && gap.missing.length === 0 && gap.coarse.length === 0;
    const hint = !eps.length ? "\u6CA1\u6709\u4ECE 09-\u5267\u672C \u91CC\u8BA4\u51FA\u4EFB\u4F55\u4E00\u96C6/\u4E00\u7AE0\u7684\u6587\u4EF6\u540D\uFF08\u5267\u96C6\u8BA4 EP01-\u2026\uFF0C\u5C0F\u8BF4\u8BA4 \u7B2C01\u7AE0.md\uFF09\u3002\u8BFB\u4E0D\u5230\u5C31\u4E0D\u62A5\u300C\u9F50\u300D\u3002" : gap.missing.length ? `\u5267\u672C\u5199\u4E86 ${eps.length} \u96C6\uFF0C\u8D26\u672C\u53EA\u8BB0\u4E86 ${gap.recordedCount} \u884C\uFF0C\u5176\u4E2D\u9010\u96C6 ${gap.exactCount} \u96C6\u3002\u5B8C\u5168\u6CA1\u8BB0\uFF1A${gap.missing.join("\u3001")}\u3002\u8865\u8D26\u672C\u4E0D\u662F\u91CD\u5199\u5267\u672C\u2014\u2014\u6BCF\u96C6\u53EA\u5199\u8FD9\u4E00\u96C6\u53D8\u4E86\u7684\u90A3\u56DB\u9879\u3002` : gap.coarse.length ? `\u96C6\u53F7\u90FD\u8986\u76D6\u5230\u4E86\uFF0C\u4F46\u5176\u4E2D ${gap.coarse.length} \u96C6\u53EA\u6709\u300CEP01\u2013EP04\u300D\u8FD9\u7C7B\u533A\u95F4\u884C\uFF0C\u6CA1\u6709\u9010\u96C6\u8BB0\u5F55\uFF08\u9010\u96C6 ${gap.exactCount}/${eps.length}\uFF09\u3002\u533A\u95F4\u884C\u5199\u4E0D\u51FA\u300CEP03 \u672B\u75A4\u5728\u5DE6\u8FD8\u662F\u53F3\u300D\u2014\u2014\u4E0B\u4E00\u96C6\u4E00\u5B9A\u4F1A\u7A7F\u5E2E\u3002\u5EFA\u8BAE\u5BF9\u8FD9 ${gap.coarse.length} \u96C6\u9010\u96C6\u8865\u4E00\u6B21 append_continuity\u3002` : "\u5267\u672C\u4E0E\u8D26\u672C\u96C6\u53F7\u5BF9\u5F97\u4E0A\uFF0C\u4E14\u6BCF\u96C6\u90FD\u6709\u9010\u96C6\u8BB0\u5F55\u3002";
    return {
      content: [
        {
          type: "text",
          text: JSON.stringify({ ok: complete, ...gap, hint })
        }
      ]
    };
  }
);
K3(
  server,
  "hook_status",
  {
    description: "\u67E5\u4F0F\u7B14\u8BE5\u4E0D\u8BE5\u6536\u4E86\uFF1A\u8BFB\u7B2C 8 \u6BB5\u7684\u4F0F\u7B14\u53F0\u8D26\uFF0C\u6309\u5F53\u524D\u5199\u5230\u7B2C\u51E0\u96C6\u7B97\u51FA\u6BCF\u6761\u7684\u72B6\u6001\uFF08\u5DF2\u57CB / \u8BE5\u5F3A\u5316 / \u8D85\u671F\u672A\u6536 / \u5DF2\u56DE\u6536 / \u5DF2\u5E9F\u5F03\uFF09\uFF0C\u5E76\u628A\u300C\u73B0\u5728\u5C31\u5F97\u5904\u7406\u300D\u7684\u6392\u5728\u524D\u9762\u3002\u5199\u6BCF\u4E00\u96C6\u4E4B\u524D\u8C03\u4E00\u6B21\u3002",
    inputSchema: {
      workingDir: external_exports.string(),
      ep: external_exports.string().optional().describe("\u5F53\u524D\u5199\u5230\u7B2C\u51E0\u96C6\uFF08\u4E24\u4F4D\u6570\uFF09\u3002\u4E0D\u4F20\u5219\u53D6\u5267\u672C\u76EE\u5F55\u91CC\u6700\u5927\u7684\u96C6\u53F7")
    },
    _meta: { ui: { visibility: ["model", "app"] } }
  },
  async ({ workingDir, ep }) => {
    workingDir = resolveProjectDir(workingDir).dir;
    let current = ep ? Number(ep.replace(/\D/g, "")) : 0;
    if (!current) {
      const dir = path12.join(workingDir, "09-\u5267\u672C");
      if (existsSync11(dir)) {
        for (const f2 of readdirSync8(dir)) {
          if (!/\.fountain$/i.test(f2)) continue;
          const m2 = f2.match(/^EP(\d+)/i);
          if (m2) current = Math.max(current, Number(m2[1]));
        }
      }
    }
    const detailDir = path12.join(workingDir, "08-\u7EC6\u8282");
    let md = "";
    if (existsSync11(detailDir)) {
      for (const f2 of readdirSync8(detailDir)) {
        if (!/\.md$/i.test(f2)) continue;
        md += readFileSync11(path12.join(detailDir, f2), "utf8") + "\n";
      }
    }
    const hooks = parseHooks(md);
    if (!hooks.length) {
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({
              ok: false,
              currentEp: current,
              note: "\u7B2C 8 \u6BB5\u6CA1\u6709\u53EF\u89E3\u6790\u7684\u4F0F\u7B14\u53F0\u8D26\u3002\u8868\u5934\u8981\u542B\u300C\u4F0F\u7B14\u300D\u300C\u57CB\u5728\u54EA\u300D\u300C\u5728\u54EA\u6536\u300D\u4E09\u5217\uFF0C\u72B6\u6001\u5217\u5199\u300C\u5DF2\u6536 / \u672A\u6536 / \u5DF2\u5E9F\u5F03\u300D\u3002"
            })
          }
        ]
      };
    }
    const r2 = reportHooks(hooks, current || 1);
    return {
      content: [
        {
          type: "text",
          text: JSON.stringify({
            ok: true,
            currentEp: r2.currentEp,
            total: r2.total,
            byState: r2.byState,
            payoffRate: Math.round(r2.payoffRate * 100) + "%",
            todo: r2.todo,
            hint: r2.todo.length ? `\u6709 ${r2.todo.length} \u6761\u50AC\u529E\uFF1A\u5148\u770B overdue \u7684\u2014\u2014\u5199\u8FD9\u4E00\u96C6\u65F6\u987A\u624B\u6536\u6389\uFF0C\u6216\u660E\u786E\u6539\u6210\u300C\u8BA1\u5212 EPxx \u6536\u300D\u3002` : "\u5F53\u524D\u6CA1\u6709\u5230\u70B9\u7684\u4F0F\u7B14\u3002"
          })
        }
      ]
    };
  }
);
K3(
  server,
  "continuity_board",
  {
    description: "\u8DE8\u96C6\u53F0\u8D26\u770B\u677F\uFF08View \u7528\uFF09\uFF1A24 \u96C6\u5404\u81EA\u8BB0\u6CA1\u8BB0\u3001\u6BCF\u96C6\u672B\u5C3E\u7684\u56DB\u9879\u72B6\u6001\u3001\u4EE5\u53CA\u54EA\u51E0\u96C6\u8FD8\u6CA1\u8BB0\u3002",
    inputSchema: { workingDir: external_exports.string() },
    _meta: { ui: { visibility: ["app"] } }
  },
  async ({ workingDir }) => {
    workingDir = resolveProjectDir(workingDir).dir;
    const scriptDir = path12.join(workingDir, "09-\u5267\u672C");
    const eps = [];
    if (existsSync11(scriptDir)) {
      for (const f2 of readdirSync8(scriptDir)) {
        if (!/\.fountain$/i.test(f2)) continue;
        const m2 = f2.match(/^EP(\d+)/i);
        if (m2) eps.push(m2[1].padStart(2, "0"));
      }
    }
    eps.sort();
    const rows2 = readContinuity(workingDir);
    const gap = ledgerGap(workingDir, eps);
    const has2 = new Set(rows2.filter((r2) => /^\d{2}$/.test(r2.ep)).map((r2) => r2.ep));
    const items = eps.map((ep) => {
      const row = rows2.find((r2) => r2.ep === ep);
      return {
        ep,
        scripted: true,
        recorded: has2.has(ep),
        time: row?.time || "",
        place: row?.place || "",
        look: row?.look || "",
        prop: row?.prop || ""
      };
    });
    return {
      content: [
        {
          type: "text",
          text: JSON.stringify({
            ok: true,
            total: eps.length,
            recorded: has2.size,
            gap,
            items,
            file: path12.join("_state", CONTINUITY_FILE)
          })
        }
      ]
    };
  }
);
